// supabase/functions/rihla-game/database.ts
async function rest(query, method = "GET", body) {
  const key = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY");
  const response = await fetch(Deno.env.get("SUPABASE_URL") + "/rest/v1/rihla_rooms?" + query, { method, headers: { apikey: key, Authorization: "Bearer " + key, "Content-Type": "application/json", Prefer: "return=representation" }, body: body === void 0 ? void 0 : JSON.stringify(body) });
  if (!response.ok) throw Error("Database request failed (" + response.status + ")");
  return response.status === 204 ? [] : response.json();
}
var env = { DB: { prepare(sql) {
  let args = [];
  return { bind(...values) {
    args = values;
    return this;
  }, async first() {
    const rows = await rest("code=eq." + encodeURIComponent(args[0]) + "&select=data,version");
    return rows[0] ?? null;
  }, async run() {
    let rows;
    if (sql.startsWith("INSERT")) rows = await rest("", "POST", { code: args[0], data: args[1], version: 0 });
    else if (sql.startsWith("UPDATE")) rows = await rest("code=eq." + encodeURIComponent(args[1]) + "&version=eq." + args[2], "PATCH", { data: args[0], version: args[2] + 1 });
    else if (sql.startsWith("DELETE")) {
      const candidates = await rest("code=like.PDF_*&select=code,data");
      rows = [];
      for (const row of candidates) if (JSON.parse(row.data).expires < args[0]) rows.push(...await rest("code=eq." + encodeURIComponent(row.code), "DELETE"));
    } else throw Error("Unsupported database operation");
    return { meta: { changes: rows.length } };
  } };
} } };

// lib/team-utils.ts
var distance = (a, b) => {
  const rad = (x) => x * Math.PI / 180;
  const d = Math.sin(rad(b.lat - a.lat) / 2) ** 2 + Math.cos(rad(a.lat)) * Math.cos(rad(b.lat)) * Math.sin(rad(b.lng - a.lng) / 2) ** 2;
  return 6371e3 * 2 * Math.atan2(Math.sqrt(d), Math.sqrt(1 - d));
};
function makeTeam(name, i) {
  return { id: uid(), name, color: ["#0df", "#c6f", "#fc6", "#5e9"][i % 4], emblem: ["\u{1F985}", "\u2B50", "\u{1F9ED}", "\u{1F30D}"][i % 4], secret: String(Math.floor(1e5 + Math.random() * 9e5)), inviteKey: uid(), members: [], collections: {}, route: [], step: 0, score: 0, success: 0, last: 0, stamps: [], errors: 0, hinted: false, opened: 0, override: false, request: false, done: false };
}
function uid() {
  const c = globalThis.crypto;
  if (typeof c.randomUUID === "function") return c.randomUUID();
  return Array.from(c.getRandomValues(new Uint8Array(16)), (n) => n.toString(16).padStart(2, "0")).join("");
}

