    "\u062A\u0636\u0645\u0651 \u062D\u062F\u0627\u0626\u0642 \u0627\u0644\u062E\u0644\u064A\u062C \u0641\u064A \u0628\u0644\u0627\u062F\u064A \u0647\u064A\u0627\u0643\u0644 \u0643\u0628\u064A\u0631\u0629 \u062A\u0634\u0628\u0647 \u0627\u0644\u0623\u0634\u062C\u0627\u0631.",
