    "\u064A\u0642\u0639 \u0645\u0637\u0627\u0631 \u0634\u0627\u0646\u063A\u064A \u0641\u064A \u0628\u0644\u0627\u062F\u064A.",
    "\u062A\u0634\u062A\u0647\u0631 \u0645\u0631\u0627\u0643\u0632 \u0627\u0644\u0637\u0639\u0627\u0645 \u0627\u0644\u0634\u0639\u0628\u064A\u0629 \u0641\u064A \u0628\u0644\u0627\u062F\u064A \u0628\u062A\u0646\u0648\u0651\u0639 \u0623\u0637\u0628\u0627\u0642\u0647\u0627.",
    "\u062A\u064F\u0632\u0631\u0639 \u0623\u0632\u0647\u0627\u0631 \u0627\u0644\u0623\u0648\u0631\u0643\u064A\u062F \u0641\u064A \u062D\u062F\u0627\u0626\u0642\u064A \u0627\u0644\u0627\u0633\u062A\u0648\u0627\u0626\u064A\u0629.",
    "\u062A\u0639\u0628\u0631 \u0642\u0646\u0648\u0627\u062A \u0645\u0627\u0626\u064A\u0629 \u0648\u0645\u0636\u0627\u0626\u0642 \u0628\u064A\u0646 \u0628\u0644\u0627\u062F\u064A \u0648\u0645\u0627\u0644\u064A\u0632\u064A\u0627."
