    "\u062A\u064F\u0645\u0627\u0631\u0633 \u0645\u0635\u0627\u0631\u0639\u0629 \u062A\u0642\u0644\u064A\u062F\u064A\u0629 \u062A\u062D\u0638\u0649 \u0628\u0634\u0639\u0628\u064A\u0629 \u0641\u064A \u0628\u0644\u0627\u062F\u064A.",
    "\u062A\u0631\u062A\u0628\u0637 \u0627\u0644\u0637\u0631\u064A\u0642\u0629 \u0627\u0644\u0645\u0631\u064A\u062F\u064A\u0629 \u0628\u0645\u062F\u064A\u0646\u0629 \u0637\u0648\u0628\u0649 \u0641\u064A \u0628\u0644\u0627\u062F\u064A.",
    "\u0639\u0627\u0635\u0645\u062A\u064A \u062F\u0627\u0643\u0627\u0631\u060C \u0648\u0623\u0637\u0644\u0651 \u0639\u0644\u0649 \u0627\u0644\u0645\u062D\u064A\u0637 \u0627\u0644\u0623\u0637\u0644\u0633\u064A \u0641\u064A \u063A\u0631\u0628 \u0623\u0641\u0631\u064A\u0642\u064A\u0627."
