    "\u062A\u064F\u0639\u0631\u0641 \u062A\u0643\u0648\u064A\u0646\u0627\u062A \u062A\u0633\u064A\u0646\u063A\u064A \u0641\u064A \u0628\u0644\u0627\u062F\u064A \u0628\u0635\u062E\u0648\u0631\u0647\u0627 \u0627\u0644\u062C\u064A\u0631\u064A\u0629 \u0627\u0644\u062D\u0627\u062F\u0651\u0629.",
    "\u062A\u0636\u0645\u0651 \u062C\u0632\u064A\u0631\u062A\u064A \u062D\u064A\u0648\u0627\u0646\u0627\u062A \u0648\u0646\u0628\u0627\u062A\u0627\u062A \u0644\u0627 \u062A\u0648\u062C\u062F \u0637\u0628\u064A\u0639\u064A\u064B\u0627 \u0641\u064A \u0623\u0645\u0627\u0643\u0646 \u0623\u062E\u0631\u0649.",
    "\u0639\u0627\u0635\u0645\u062A\u064A \u0623\u0646\u062A\u0627\u0646\u0627\u0646\u0627\u0631\u064A\u0641\u0648\u060C \u0648\u064A\u0641\u0635\u0644\u0646\u064A \u0645\u0636\u064A\u0642 \u0645\u0648\u0632\u0645\u0628\u064A\u0642 \u0639\u0646 \u0627\u0644\u0628\u0631\u0651 \u0627\u0644\u0623\u0641\u0631\u064A\u0642\u064A."
