    "\u062A\u064F\u0639\u062F\u0651 \u0627\u0644\u0633\u0627\u0645\u0628\u0627 \u0645\u0646 \u0623\u0634\u0647\u0631 \u0631\u0642\u0635\u0627\u062A\u064A \u0648\u0625\u064A\u0642\u0627\u0639\u0627\u062A\u064A \u0627\u0644\u0645\u0648\u0633\u064A\u0642\u064A\u0629.",
