    "\u064A\u0642\u0639 \u0634\u0627\u0637\u0626 \u0643\u0648\u0628\u0627\u0643\u0627\u0628\u0627\u0646\u0627 \u0641\u064A \u0625\u062D\u062F\u0649 \u0623\u0634\u0647\u0631 \u0645\u062F\u0646\u064A.",
