    "\u0639\u0627\u0635\u0645\u062A\u064A \u0628\u0631\u0627\u0632\u064A\u0644\u064A\u0627\u060C \u0648\u0623\u0643\u0628\u0631 \u0645\u062F\u0646\u064A \u0633\u0627\u0648 \u0628\u0627\u0648\u0644\u0648."
