function hydrateClues(room) {
  let changed = false;
  if (room.status !== "waiting") return false;
  for (const q of room.library) {
    if (!Array.isArray(q.clues) || q.clues.length === 0 && cooperativeClues[q.country]?.length) {
      q.clues = [...cooperativeClues[q.country] || []];
      changed = true;
    }
  }
  return changed;
}

