// app/api/codes/route.ts
var headers = { "Cache-Control": "no-store", "Referrer-Policy": "no-referrer" };
async function POST2(req) {
  try {
    const b = await req.json();
    const db = env.DB;
    if (!db) return Response.json({ error: "\u0642\u0627\u0639\u062F\u0629 \u0627\u0644\u0628\u064A\u0627\u0646\u0627\u062A \u063A\u064A\u0631 \u0645\u062A\u0627\u062D\u0629" }, { status: 503 });
    const row = await db.prepare("SELECT data,version FROM rooms WHERE code=?").bind(String(b.code || "").toUpperCase()).first();
    if (!row || JSON.parse(row.data).token !== b.token) return Response.json({ error: "\u0644\u0644\u0645\u0646\u0638\u0651\u0645 \u0641\u0642\u0637" }, { status: 403 });
    if (typeof b.pdf !== "string" || b.pdf.length > 19e5 || !b.pdf.startsWith("JVBERi0") || !/^[A-Za-z0-9+/]*={0,2}$/.test(b.pdf)) return Response.json({ error: "\u0645\u0644\u0641 PDF \u063A\u064A\u0631 \u0635\u0627\u0644\u062D \u0623\u0648 \u0643\u0628\u064A\u0631 \u062C\u062F\u064B\u0627" }, { status: 400 });
    const id = "PDF_" + crypto.randomUUID().replaceAll("-", ""), expires = Date.now() + 15 * 6e4;
    await db.prepare("DELETE FROM rooms WHERE code LIKE 'PDF_%' AND json_extract(data,'$.expires') < ?").bind(Date.now()).run();
    await db.prepare("INSERT INTO rooms(code,data,version) VALUES(?,?,0)").bind(id, JSON.stringify({ pdf: b.pdf, expires, name: "RIHLA_CODES_" + String(b.code).replace(/[^a-z0-9]/gi, "") + ".pdf" })).run();
    return Response.json({ url: Deno.env.get("SUPABASE_URL") + "/functions/v1/rihla-game/codes?id=" + id, expires }, { headers });
  } catch {
    return Response.json({ error: "\u062A\u0639\u0630\u0651\u0631 \u062A\u062C\u0647\u064A\u0632 \u0631\u0627\u0628\u0637 \u0627\u0644\u062A\u0646\u0632\u064A\u0644\u060C \u062D\u0627\u0648\u0644 \u0645\u062C\u062F\u062F\u064B\u0627" }, { status: 500 });
  }
}
async function GET(req) {
  const id = new URL(req.url).searchParams.get("id") || "";
  if (!/^PDF_[a-f0-9]{32}$/.test(id)) return new Response("Not found", { status: 404, headers });
  const db = env.DB;
  if (!db) return new Response("Unavailable", { status: 503, headers });
  const row = await db.prepare("SELECT data,version FROM rooms WHERE code=?").bind(id).first();
  if (!row) return new Response("Not found", { status: 404, headers });
  const data = JSON.parse(row.data);
  if (data.expires < Date.now()) return new Response("Expired - generate a new PDF from the organizer screen", { status: 410, headers });
  return new Response(Uint8Array.from(atob(data.pdf), (ch) => ch.charCodeAt(0)), { headers: { ...headers, "Content-Type": "application/pdf", "Content-Disposition": `attachment; filename="${data.name}"`, "X-Content-Type-Options": "nosniff" } });
}

